"""Universal Administration Operations Center UI (v1.7.0)."""


def operations_center_html():
    return r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Administration Operations Center</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#182333;background:#f4f7fb;--blue:#174ea6;--line:#dbe3ee;--muted:#65748a}
*{box-sizing:border-box}body{margin:0}header{background:linear-gradient(115deg,#143c79,#2366b5);color:white;padding:22px 28px}header h1{margin:0;font-size:24px}header p{margin:6px 0 0;opacity:.85}.shell{max-width:1400px;margin:auto;padding:20px}.grid{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:14px}.card{background:white;border:1px solid var(--line);border-radius:12px;padding:16px;box-shadow:0 2px 7px #1b365b08}.metric{font-size:28px;font-weight:750;color:var(--blue);margin:4px 0}.label{font-size:13px;color:var(--muted)}.section{margin-top:20px}.section h2{font-size:18px;margin:0 0 12px}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:10px 0}.toolbar select,.toolbar input,.form input,.form select,.form textarea{border:1px solid var(--line);border-radius:8px;padding:9px 10px;background:#fff;color:#182333}.btn{border:0;border-radius:8px;padding:9px 12px;background:var(--blue);color:white;font-weight:600;cursor:pointer}.btn.secondary{background:#e8eff9;color:#1c4d8f}.btn.small{padding:6px 9px;font-size:12px}.table-wrap{overflow:auto;background:#fff;border:1px solid var(--line);border-radius:12px}table{border-collapse:collapse;width:100%;min-width:720px}th,td{text-align:left;padding:11px 12px;border-bottom:1px solid var(--line);font-size:13px}th{background:#f8fafd;color:#4d6078;font-weight:650}tr:last-child td{border-bottom:0}.badge{border-radius:20px;padding:4px 8px;background:#eef3fb;font-size:11px}.forms{display:grid;grid-template-columns:1fr 1fr;gap:16px}.form{display:grid;gap:9px}.form label{font-size:12px;color:var(--muted)}.form textarea{min-height:70px}.notice{padding:12px;border-radius:9px;background:#eef5ff;color:#31577e;margin:12px 0}.hidden{display:none}.empty{padding:22px;text-align:center;color:var(--muted)}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.forms{grid-template-columns:1fr}}@media(max-width:520px){header{padding:18px}.shell{padding:12px}.grid{grid-template-columns:1fr 1fr}.metric{font-size:23px}}
</style></head><body>
<header><h1>Administration Operations Center</h1><p>Universal administration operations, service workload and operational control</p></header>
<div class="shell">
<div class="toolbar"><button class="btn" onclick="refreshAll()">Refresh dashboard</button><span id="lastRefresh" class="label"></span></div>
<div id="metrics" class="grid"></div>
<div class="section"><h2>License, Permit & Renewal Management</h2><div class="notice">Renewal Register monitoring is available. Actual notification delivery remains pending verified integration with the Framework Notification Engine.</div><div id="renewalMetrics" class="grid"></div><div class="toolbar"><button class="btn secondary" onclick="loadRenewals()">Refresh renewals</button><button class="btn secondary" onclick="setDomain('renewals')">Open Renewal Register records</button></div><div class="table-wrap"><table><thead><tr><th>Renewal Item</th><th>Category</th><th>Expiry Date</th><th>Days Remaining</th><th>State</th><th>Responsible Officer</th></tr></thead><tbody id="renewalRows"><tr><td colspan="6" class="empty">Loading renewal data...</td></tr></tbody></table></div></div>
<div class="section"><h2>Dedicated administration workbenches</h2><div class="toolbar" id="workbenchButtons">
<button class="btn secondary" onclick="setDomain('facilities')">Facilities & Maintenance</button>
<button class="btn secondary" onclick="setDomain('vehicles')">Fleet & Transport</button>
<button class="btn secondary" onclick="setDomain('supplies')">Supplies & Inventory</button>
<button class="btn secondary" onclick="setDomain('correspondence')">Correspondence & Records</button>
<button class="btn secondary" onclick="setDomain('events')">Events & Visitors</button>
<button class="btn secondary" onclick="setDomain('travel')">Travel Management</button>
<button class="btn secondary" onclick="loadRenewals()">Renewals</button>
</div></div>
<div class="section"><h2>Facilities & Maintenance</h2><div class="forms">
<div class="card"><h3>Create work order</h3><div class="form">
<label>Title</label><input id="woTitle"><label>Facility record ID</label><input id="woFacility">
<label>Work type</label><input id="woType" placeholder="Preventive / Corrective"><label>Scheduled date</label><input id="woDate" type="date">
<label>Priority</label><select id="woPriority"><option>Normal</option><option>Low</option><option>High</option><option>Urgent</option></select>
<label>Recurrence</label><select id="woRecurrence"><option>None</option><option>Weekly</option><option>Monthly</option><option>Quarterly</option><option>Semi-Annual</option><option>Annual</option></select>
<button class="btn" onclick="createWorkOrder()">Create work order</button></div></div>
<div class="card"><h3>Complete work order</h3><div class="form"><label>Work order ID</label><input id="woCompleteId"><label>Actual cost</label><input id="woCost" type="number" step="0.01"><label>Completion notes</label><textarea id="woNotes"></textarea><button class="btn" onclick="completeWorkOrder()">Complete work order</button></div></div>
</div></div>
<div class="section"><h2>Fleet & Transport</h2><div class="forms">
<div class="card"><h3>Fleet alerts</h3><div class="form"><label>Alert horizon (days)</label><input id="fleetDays" type="number" value="30"><button class="btn" onclick="loadFleetAlerts()">Check fleet alerts</button></div><div id="fleetAlerts" class="label"></div></div>
<div class="card"><h3>Trip conflict check</h3><div class="form"><label>Vehicle ID</label><input id="tripVehicle"><label>Driver ID</label><input id="tripDriver"><label>Departure</label><input id="tripDeparture" type="datetime-local"><label>Return</label><input id="tripReturn" type="datetime-local"><button class="btn" onclick="checkTripConflicts()">Check conflicts</button><div id="tripConflictResult"></div></div></div>
</div></div>
<div class="section"><h2>Events & Facilities Booking</h2><div class="card"><div class="form">
<label>Venue / facility ID</label><input id="eventVenue"><label>Start</label><input id="eventStart" type="datetime-local"><label>End</label><input id="eventEnd" type="datetime-local"><button class="btn" onclick="checkVenueConflicts()">Check booking conflicts</button><div id="venueConflictResult"></div>
</div></div></div>
<div class="section"><h2>Correspondence, Records & Knowledge</h2><div class="forms">
<div class="card"><h3>Knowledge / SOP search</h3><div class="form"><label>Search</label><input id="knowledgeQuery"><button class="btn" onclick="searchKnowledge()">Search knowledge base</button><div id="knowledgeResults"></div></div></div>
<div class="card"><h3>Operational reminders</h3><div class="notice">Use the domain record register to review response deadlines, correspondence status, visitor records, travel requests, vendors and automation rules. Workflow and approvals are governed by the existing configurable framework engine.</div></div>
</div></div>

<div class="section"><h2>Operational records</h2><div class="toolbar"><select id="domain" onchange="loadRecords()"><option value="tasks">Administrative Tasks</option><option value="facilities">Facilities</option><option value="work_orders">Maintenance Work Orders</option><option value="vehicles">Fleet</option><option value="trips">Transport Trips</option><option value="vendors">Vendors</option><option value="supplies">Office Supplies</option><option value="stock_transactions">Stock Transactions</option><option value="correspondence">Correspondence</option><option value="events">Events</option><option value="visitors">Visitors</option><option value="travel">Travel</option><option value="automation_rules">Automation Rules</option><option value="knowledge_articles">Knowledge Articles</option><option value="renewals">Renewal Register</option></select><input id="search" placeholder="Filter visible records" oninput="filterRows()"><button class="btn secondary" onclick="loadRecords()">Load records</button></div><div class="table-wrap"><table><thead><tr><th>Record</th><th>Status</th><th>Priority</th><th>Last modified</th><th>Action</th></tr></thead><tbody id="records"><tr><td colspan="5" class="empty">Select a domain and load records.</td></tr></tbody></table></div></div>
<div class="section"><h2>Quick operations</h2><div class="forms">
<div class="card"><h3>Create administrative task</h3><div class="form"><label>Task title</label><input id="taskTitle" placeholder="Task title"><label>Priority</label><select id="taskPriority"><option>Medium</option><option>Low</option><option>High</option><option>Urgent</option></select><label>Assigned to (user ID)</label><input id="taskOwner" placeholder="Optional"><label>Due date</label><input id="taskDue" type="date"><label>Category</label><input id="taskCategory" placeholder="Optional category"><button class="btn" onclick="createTask()">Create task</button></div></div>
<div class="card"><h3>Supply transaction</h3><div class="form"><label>Supply item record ID</label><input id="stockItem" placeholder="Supply Item name"><label>Transaction type</label><select id="stockType"><option>Receipt</option><option>Issue</option><option>Return</option><option>Adjustment</option></select><label>Quantity</label><input id="stockQty" type="number" min="0.001" step="0.001"><label>Notes</label><textarea id="stockNotes"></textarea><button class="btn" onclick="processStock()">Process transaction</button></div></div>
</div></div><div id="message" class="notice hidden"></div>
</div>
<script>
const api=(path,opts={})=>fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...opts}).then(async r=>{let d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||d.message||r.statusText);return d});
function show(msg,err=false){const e=document.getElementById('message');e.textContent=msg;e.classList.remove('hidden');e.style.background=err?'#fff0f0':'#eef5ff';e.style.color=err?'#9b2525':'#31577e';setTimeout(()=>e.classList.add('hidden'),6000)}
function metric(title,value,detail){return `<div class="card"><div class="label">${title}</div><div class="metric">${value??0}</div><div class="label">${detail||''}</div></div>`}
async function refreshAll(){try{const d=await api('/api/admin/universal/operations-dashboard');let cards=[];cards.push(metric('Open / overdue tasks',d.tasks?.open,d.tasks?.overdue+' overdue'));cards.push(metric('Facilities / open work orders',d.facilities?.active,d.facilities?.open_work_orders+' open work orders'));cards.push(metric('Fleet / service due',d.fleet?.vehicles,d.fleet?.service_due+' service due'));cards.push(metric('Pending trips',d.fleet?.trips_pending,'Requested or scheduled'));cards.push(metric('Active vendors',d.vendors?.active,d.vendors?.contracts_expiring+' contracts expiring'));cards.push(metric('Supply items below reorder',d.supplies?.below_reorder,d.supplies?.items+' catalogue items'));cards.push(metric('Open correspondence',d.correspondence?.open,d.correspondence?.overdue_responses+' response overdue'));cards.push(metric('Planned events',d.events?.planned,d.visitors?.expected_today+' visitors expected today'));document.getElementById('metrics').innerHTML=cards.join('');document.getElementById('lastRefresh').textContent='Updated '+new Date().toLocaleString();await loadRecords();await loadRenewals()}catch(e){show('Dashboard load failed: '+e.message,true)}}

async function loadRenewals(){try{const d=await api('/api/admin/renewals/dashboard');const exp=d.expired||[],due=d.due_soon||[],up=d.upcoming||[];document.getElementById('renewalMetrics').innerHTML=[metric('Expired renewals',exp.length,'Expired items requiring action'),metric('Due soon',due.length,'Within renewal lead window'),metric('Upcoming',up.length,'Not yet in due window'),metric('Active renewal records',d.total_active||0,'Active or in progress')].join('');let rows=[...exp.map(x=>({...x,_state:'Expired'})),...due.map(x=>({...x,_state:'Due Soon'})),...up.map(x=>({...x,_state:'Upcoming'}))];rows.sort((a,b)=>(a.days_remaining??999999)-(b.days_remaining??999999));document.getElementById('renewalRows').innerHTML=rows.length?rows.map(r=>`<tr><td><strong>${r.renewal_title||r.name}</strong><div class="label">${r.name||''}</div></td><td>${r.renewal_category||'—'}</td><td>${r.expiry_date||'—'}</td><td>${r.days_remaining??'—'}</td><td><span class="badge">${r._state}</span></td><td>${r.responsible_officer||'—'}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No renewal records found.</td></tr>'}catch(e){document.getElementById('renewalRows').innerHTML='<tr><td colspan="6" class="empty">Renewal dashboard unavailable: '+e.message+'</td></tr>'}}

async function loadRecords(){let domain=document.getElementById('domain').value;try{const rows=await api('/api/admin/universal/records/'+encodeURIComponent(domain)+'?limit=200');let html=rows.map(r=>`<tr data-search="${(r.name+' '+(r.title||'')+' '+(r.status||'')).toLowerCase()}"><td><strong>${r.title||r.name}</strong><div class="label">${r.name}</div></td><td><span class="badge">${r.status||'—'}</span></td><td>${r.priority||'—'}</td><td>${r.modified||'—'}</td><td>${domain==='tasks'&&r.status!=='Completed'?`<button class="btn small" onclick="completeTask('${r.name}')">Complete</button>`:''}</td></tr>`).join('');document.getElementById('records').innerHTML=html||'<tr><td colspan="5" class="empty">No records found.</td></tr>';filterRows()}catch(e){show('Record list failed: '+e.message,true)}}

function setDomain(domain){document.getElementById('domain').value=domain;loadRecords();}
async function createWorkOrder(){try{let payload={title:document.getElementById('woTitle').value,facility:document.getElementById('woFacility').value,work_type:document.getElementById('woType').value,scheduled_date:document.getElementById('woDate').value||null,priority:document.getElementById('woPriority').value,recurrence:document.getElementById('woRecurrence').value};let r=await api('/api/admin/universal/work-orders',{method:'POST',body:JSON.stringify(payload)});show('Work order created: '+(r.name||r.title||'success'));setDomain('work_orders')}catch(e){show('Work order creation failed: '+e.message,true)}}


async function completeWorkOrder(){try{let id=document.getElementById('woCompleteId').value;let r=await api('/api/admin/universal/work-orders/'+encodeURIComponent(id)+'/complete',{method:'POST',body:JSON.stringify({actual_cost:document.getElementById('woCost').value||null,notes:document.getElementById('woNotes').value})});show('Work order completed. Next scheduled work order: '+(r.next_work_order||'none'));setDomain('work_orders')}catch(e){show('Completion failed: '+e.message,true)}}


async function loadFleetAlerts(){try{let days=document.getElementById('fleetDays').value||30;let rows=await api('/api/admin/universal/fleet/alerts?days_ahead='+encodeURIComponent(days));document.getElementById('fleetAlerts').innerHTML=rows.length?rows.map(x=>`${x.title||x.vehicle} — ${x.alert_type} due ${x.due_date} (${x.days_remaining} days)`).join('<br>'):'No fleet alerts in this horizon'}catch(e){show('Fleet alerts failed: '+e.message,true)}}


async function checkTripConflicts(){try{let payload={vehicle:document.getElementById('tripVehicle').value||null,driver:document.getElementById('tripDriver').value||null,departure:document.getElementById('tripDeparture').value,returning:document.getElementById('tripReturn').value};let rows=await api('/api/admin/universal/fleet/trip-conflicts',{method:'POST',body:JSON.stringify(payload)});document.getElementById('tripConflictResult').textContent=rows.length?JSON.stringify(rows):'No conflicts detected'}catch(e){show('Trip conflict check failed: '+e.message,true)}}


async function checkVenueConflicts(){try{let payload={venue:document.getElementById('eventVenue').value,start:document.getElementById('eventStart').value,end:document.getElementById('eventEnd').value};let rows=await api('/api/admin/universal/events/venue-conflicts',{method:'POST',body:JSON.stringify(payload)});document.getElementById('venueConflictResult').textContent=rows.length?JSON.stringify(rows):'No venue conflicts detected'}catch(e){show('Venue conflict check failed: '+e.message,true)}}


async function searchKnowledge(){try{let q=document.getElementById('knowledgeQuery').value;let rows=await api('/api/admin/universal/knowledge/search?q='+encodeURIComponent(q));document.getElementById('knowledgeResults').innerHTML=rows.length?rows.map(x=>`<div><strong>${x.title}</strong> — ${x.category||''}</div>`).join(''):'No published knowledge articles found'}catch(e){show('Knowledge search failed: '+e.message,true)}
function filterRows(){let q=document.getElementById('search').value.toLowerCase();document.querySelectorAll('#records tr[data-search]').forEach(r=>r.style.display=r.dataset.search.includes(q)?'':'none')}}


async function createTask(){let title=document.getElementById('taskTitle').value.trim();if(!title)return show('Enter a task title.',true);let payload={title,priority:document.getElementById('taskPriority').value,assigned_to:document.getElementById('taskOwner').value||null,due_date:document.getElementById('taskDue').value||null,category:document.getElementById('taskCategory').value||null};try{await api('/api/admin/universal/tasks',{method:'POST',body:JSON.stringify(payload)});show('Task created successfully.');document.getElementById('taskTitle').value='';refreshAll()}catch(e){show('Task creation failed: '+e.message,true)}}
async function processStock(){let item=document.getElementById('stockItem').value.trim(),qty=Number(document.getElementById('stockQty').value);if(!item||!qty)return show('Supply item and quantity are required.',true);let payload={supply_item:item,transaction_type:document.getElementById('stockType').value,quantity:qty,notes:document.getElementById('stockNotes').value};try{await api('/api/admin/universal/supplies/transactions',{method:'POST',body:JSON.stringify(payload)});show('Supply transaction processed.');refreshAll()}catch(e){show('Stock transaction failed: '+e.message,true)}}
async function completeTask(name){if(!confirm('Mark task '+name+' as completed?'))return;try{await api('/api/admin/universal/tasks/'+encodeURIComponent(name)+'/complete',{method:'POST',body:JSON.stringify({notes:'Completed from Administration Operations Center'})});show('Task completed.');refreshAll()}catch(e){show('Task completion failed: '+e.message,true)}}
refreshAll();
</script></body></html>'''
